import{_ as i,a0 as o,w as s,s as u,I as e,x as t,a1 as r,A as n,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"GNOME 2 的 Linux 文件管理器 Caja | LCTT x X-CMD","titleTemplate":false,"description":"GNOME 2 的 Linux 文件管理器 Caja | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME 2 的 Linux 文件管理器 Caja | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME 2 的 Linux 文件管理器 Caja | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221210.0 ⭐️ How to use the Linux file manager for GNOME 2","title":"GNOME 2 的 Linux 文件管理器 Caja","tag":"202302","desc":""},"relativePath":"202302/20221210.0 ⭐️ How to use the Linux file manager for GNOME 2.md","filePath":"[post].md"}'),m={name:"202302/20221210.0 ⭐️ How to use the Linux file manager for GNOME 2.md"};function d(f,a,j,C,x,g){const l=o("Link");return s(),u("div",null,[a[23]||(a[23]=e("h1",{id:"gnome-2-的-linux-文件管理器-caja",tabindex:"-1"},[t("GNOME 2 的 Linux 文件管理器 Caja "),e("a",{class:"header-anchor",href:"#gnome-2-的-linux-文件管理器-caja","aria-label":"Permalink to “GNOME 2 的 Linux 文件管理器 Caja”"},"​")],-1)),a[24]||(a[24]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202302/12/093538qnlj0jdunz10n17c.jpg",alt:""})],-1)),a[25]||(a[25]=e("blockquote",null,[e("p",null,"如果你是 GNOME 2 的粉丝，那么你肯定会发现 Caja 很熟悉，如果你从来没有使用过 GNOME 2，那么你可能会在 Mate 中找到你的新宠桌面。")],-1)),e("p",null,[a[1]||(a[1]=t("在 GNOME 3 之前是 GNOME 2（废话），在其作为常见的默认 Linux 桌面之一的统治期间，它拥有了一个热心的粉丝群。",-1)),r(l,{href:"https://opensource.com/article/19/12/mate-linux-desktop"},{default:n(()=>[...a[0]||(a[0]=[t("Mate 项目",-1)])]),_:1}),a[2]||(a[2]=t("（以植物 ",-1)),a[3]||(a[3]=e("em",null,"yerba mate",-1)),a[4]||(a[4]=t(" 命名）最初是为了延续 GNOME 2 桌面的生命力，它起初是使用 GTK 2（基于 GNOME 2 的工具包）开发的，后来升级为 GTK 3。该桌面包含了一个 Caja 文件管理器，这是一个简单而强大的应用，可以帮助你分类和组织你的数据。",-1))]),a[26]||(a[26]=e("h3",{id:"安装-caja",tabindex:"-1"},[t("安装 Caja "),e("a",{class:"header-anchor",href:"#安装-caja","aria-label":"Permalink to “安装 Caja”"},"​")],-1)),a[27]||(a[27]=e("p",null,"Caja 并不完全是一个独立的应用。它与 Mate 桌面紧密相连，所以要试用它，你必须安装 Mate。",-1)),e("p",null,[a[6]||(a[6]=t("你可能会发现 Mate 包含在你的 Linux 发行版的仓库中，或者你可以下载并安装一个将 Mate 作为默认桌面的发行版。不过，在你安装之前，要注意它是为了提供完整的桌面体验，所以会和桌面一起安装许多 Mate 应用。如果你运行一个不同的桌面，你可能会发现自己有多余的应用（两个 PDF 阅读器，两个媒体播放器，两个文件管理器，等等）。要评估 Caja 不会对你的电脑做重大改动，可以使用 ",-1)),r(l,{href:"https://opensource.com/article/19/5/getting-started-gnome-boxes-virtualization"},{default:n(()=>[...a[5]||(a[5]=[t("GNOME Boxes",-1)])]),_:1}),a[7]||(a[7]=t(" 在虚拟机中安装一个基于 Mate 的发行版。",-1))]),a[28]||(a[28]=p('<p><img src="https://opensource.com/sites/default/files/2022-10/caja.file%20manager.png" alt="Image of the  Caja file manager."></p><h3 id="清晰的布局" tabindex="-1">清晰的布局 <a class="header-anchor" href="#清晰的布局" aria-label="Permalink to “清晰的布局”">​</a></h3><p>你可能首先注意到的是 Caja 的清晰而直接的布局。在 Caja 窗口的顶部有一个工具栏，上面有一些常用任务的按钮。我喜欢这样的设计。功能不是隐藏在右键菜单中，也不是只有在操作后才能发现，更不是埋在菜单中。窗口的“显而易见”的操作被直接列在上面。</p><p>主工具栏下面是位置栏。它显示你当前的路径，可以是一系列的按钮，也可以是可编辑的文本。使用路径左边的 “<ruby>编辑<rt>Edit</rt></ruby>” 按钮来切换它是否可编辑。</p><h3 id="可配置" tabindex="-1">可配置 <a class="header-anchor" href="#可配置" aria-label="Permalink to “可配置”">​</a></h3><p>对于 GNOME 2 或 Caja 的长期用户来说，主工具栏可能是多余的，尤其是当你知道了调用常用操作的键盘快捷键后。这就是为什么 Caja 的界面是可配置的。你可以从 “<ruby>查看<rt>View</rt></ruby>” 菜单中禁用 Caja 窗口的主要组件，包括：</p><ul><li>主工具条</li><li>位置栏</li><li>侧面板</li><li>附加面板</li><li>状态栏</li></ul><p>简而言之，你可以按你的想法精简 Caja。</p><p><img src="https://opensource.com/sites/default/files/2022-10/caja-minimal-layout.png" alt="Image of a minimal Caja layout."></p><h3 id="标记你的文件夹" tabindex="-1">标记你的文件夹 <a class="header-anchor" href="#标记你的文件夹" aria-label="Permalink to “标记你的文件夹”">​</a></h3><p>有些人是 “可视化” 人。他们喜欢根据自己对数据的看法来组织文件和文件夹，而不是根据计算机对数据的解释。例如，如果对你来说最重要的两个文件夹是<strong>音乐</strong>和<strong>工作</strong>，就很难让计算机相信这两者之间有任何关系。按字母顺序两者也排不到一起，而且每个文件夹的内容可能完全不同（一个是媒体文件，另一个是电子表格）。</p><h3 id="caja-提供了一些帮助" tabindex="-1">Caja 提供了一些帮助 <a class="header-anchor" href="#caja-提供了一些帮助" aria-label="Permalink to “Caja 提供了一些帮助”">​</a></h3><p>使用 Caja，你可以在一个窗口内手动放置目录，Caja 会记住这个位置。更重要的是，Caja 有多种标志可供你用作视觉标签。你可以在 “<ruby>编辑<rt>Edit</rt></ruby>” 菜单的 “<ruby>背景和标志<rt>Backgrounds and Emblems</rt></ruby>” 中找到它们。将它们拖放到文件和文件夹中以帮助它们区分。</p><p><img src="https://opensource.com/sites/default/files/2022-10/caja-emblem.webp" alt="Image of emblems in Caja."></p><h3 id="caja" tabindex="-1">Caja <a class="header-anchor" href="#caja" aria-label="Permalink to “Caja”">​</a></h3><p>Caja 是最诱人的文件管理器之一。它的可配置性足以吸引许多不同的使用场景，而且在这些配置选项中，你很可能找到适合你的工作流程。如果你是 GNOME 2 的粉丝，那么你肯定会发现 Caja 很熟悉，如果你从来没有使用过 GNOME 2，那么你可能会在 Mate 中找到你的新宠桌面。</p><hr>',17)),e("p",null,[a[9]||(a[9]=t("via: ",-1)),r(l,{href:"https://opensource.com/article/22/12/linux-file-manager-caja"},{default:n(()=>[...a[8]||(a[8]=[t("https://opensource.com/article/22/12/linux-file-manager-caja",-1)])]),_:1})]),e("p",null,[a[14]||(a[14]=t("作者：",-1)),r(l,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[10]||(a[10]=[t("Seth Kenlon",-1)])]),_:1}),a[15]||(a[15]=t(" 选题：",-1)),r(l,{href:"https://github.com/lkxed"},{default:n(()=>[...a[11]||(a[11]=[t("lkxed",-1)])]),_:1}),a[16]||(a[16]=t(" 译者：",-1)),r(l,{href:"https://github.com/geekpi"},{default:n(()=>[...a[12]||(a[12]=[t("geekpi",-1)])]),_:1}),a[17]||(a[17]=t(" 校对：",-1)),r(l,{href:"https://github.com/wxy"},{default:n(()=>[...a[13]||(a[13]=[t("wxy",-1)])]),_:1})]),e("p",null,[a[20]||(a[20]=t("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[18]||(a[18]=[t("LCTT",-1)])]),_:1}),a[21]||(a[21]=t(" 原创编译，",-1)),r(l,{href:"https://linux.cn/"},{default:n(()=>[...a[19]||(a[19]=[t("Linux中国",-1)])]),_:1}),a[22]||(a[22]=t(" 荣誉推出",-1))])])}const E=i(m,[["render",d]]);export{N as __pageData,E as default};
